def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Selection Algorithm.
    The average time complexity is O(n) and the worst-case time complexity is O(n^2).
    """

    if not 1 <= k <= len(nums):
        raise ValueError("k must be in the range of 1 to the length of nums")

    def selection(left, right, k_smallest):
        if left == right:  # Only one element
            return nums[left]

        pivot_index = left + (right - left) // 2
        pivot_value = nums[pivot_index]

        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]

        if k_smallest == store_index:
            return nums[store_index]
        elif k_smallest < store_index:
            return selection(left, store_index - 1, k_smallest)
        else:
            return selection(store_index + 1, right, k_smallest)

    return selection(0, len(nums) - 1, k - 1)
